using System.ClientModel;
using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Eval;

[TestClass]
public class CoachEvalTests
{
    private static TracerProvider? s_tracer;
    private static ReportingConfiguration? s_reportingConfig;
    private static readonly string s_resultsDir =
        Path.Combine(Path.GetTempPath(), "MyApp.Eval", "results");

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        // --- Telemetry mode: capture OTel traces from Microsoft.Extensions.AI ---
        s_tracer = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("Azure.AI.OpenAI")
            .AddConsoleExporter()
            .Build();

        // --- Quality mode: coherence, relevance, fluency, completeness, groundedness ---
        IEvaluator[] evaluators =
        [
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new CompletenessEvaluator(),
            new GroundednessEvaluator(),
        ];

        // --- Compare mode: disk-based storage enables cross-run comparison ---
        var storage = new DiskBasedReportingStorage(s_resultsDir);
        s_reportingConfig = new ReportingConfiguration(storage, evaluators);
    }

    [ClassCleanup]
    public static void Cleanup() => s_tracer?.Dispose();

    #region Helpers

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT env var.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY env var.");

        var client = new AzureOpenAIClient(
            new Uri(endpoint),
            new ApiKeyCredential(key));

        return client.GetChatClient("gpt-4o-mini").AsIChatClient();
    }

    private static ChatConfiguration CreateChatConfiguration()
    {
        return new ChatConfiguration(CreateChatClient());
    }

    #endregion

    [TestMethod]
    public async Task Quality_CoachGreeting()
    {
        await using var run = await s_reportingConfig!.CreateScenarioRunAsync(
            "coach-greeting", CreateChatConfiguration());

        List<ChatMessage> messages =
        [
            new(ChatRole.User, "I'm feeling stuck in my career. Can you coach me?")
        ];

        var response = await run.ChatClient!.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Quality_GoalSetting()
    {
        await using var run = await s_reportingConfig!.CreateScenarioRunAsync(
            "coach-goal-setting", CreateChatConfiguration());

        List<ChatMessage> messages =
        [
            new(ChatRole.User, "Help me set a SMART goal for learning a new programming language.")
        ];

        var response = await run.ChatClient!.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Quality_MultiTurnCoaching()
    {
        await using var run = await s_reportingConfig!.CreateScenarioRunAsync(
            "coach-multi-turn", CreateChatConfiguration());

        List<ChatMessage> messages =
        [
            new(ChatRole.User, "I want to transition from backend to full-stack development.")
        ];

        var response = await run.ChatClient!.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        messages.Add(new(ChatRole.User, "What should I focus on first?"));

        response = await run.ChatClient!.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);
    }
}

